def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    # Always cooperator: exploit after short grace period.
    if op_d == 0:
        if n < 3:
            return 'C'
        return 'D'

    # Always defector: defect.
    if op_c == 0:
        return 'D'

    # Detect pure tit-for-tat / mirroring opponent:
    # opponent's current move equals our previous move for most of the match.
    if n >= 4:
        matches = 0
        for i in range(1, n):
            if op[i] == me[i - 1]:
                matches += 1
        if matches >= n - 2:
            # We can exploit by mixing, but avoid triggering a long D-war.
            # If they mirrored our D, give C; if they mirrored our C, occasionally D.
            if op[-1] == 'D':
                return 'C'
            if n >= 95:
                return 'D'
            return 'C'

    # Detect "always defects after first C" type.
    if n >= 3 and op[0] == 'C' and op_d >= n - 1:
        return 'D'

    # Grim trigger detection: if we defected at some point and they've defected ever since.
    first_my_d = -1
    for i in range(n):
        if me[i] == 'D':
            first_my_d = i
            break
    if first_my_d >= 0 and first_my_d + 1 < n:
        all_d_after = True
        for i in range(first_my_d + 1, n):
            if op[i] != 'D':
                all_d_after = False
                break
        if all_d_after:
            return 'D'

    # Count recent opponent cooperation.
    recent = op[-8:]
    rn = len(recent)
    r_c = recent.count('C')
    r_d = rn - r_c

    # Final rounds: exploit if opponent is generally cooperative.
    if n >= 96:
        if op_d * 3 <= n:
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Late game exploitation window.
    if n >= 88:
        if op_c * 5 >= n * 4:
            return 'D'
        if r_d * 2 > rn:
            return 'D'
        return 'C'

    # If opponent is heavily defecting recently, retaliate.
    if r_d >= 6:
        return 'D'
    if op_d * 2 > n and r_d >= 3:
        return 'D'

    # Very cooperative opponent: cooperate, mostly.
    if op_d * 5 <= n:
        return 'C'

    last = op[-1]
    if last == 'D':
        # Count trailing defection run.
        run = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                run += 1
            else:
                break
        if run >= 3:
            return 'D'
        if run == 2:
            # Try to break the cycle occasionally.
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        # Single defection: retaliate, but forgive if we already retaliated once.
        if n >= 2 and me[-1] == 'D' and me[-2] == 'D' and op[-2] == 'C':
            return 'C'
        if n >= 2 and op[-2] == 'C' and me[-1] == 'D':
            return 'C'
        return 'D'
    else:
        # Opponent cooperated.
        if op_d * 2 > n:
            # Mixed: probe occasionally to test.
            if n % 11 == 0:
                return 'D'
            return 'C'
        return 'C'
